// ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
// 
// CalcStoichNum - calculate stoichiometric numbers
//   Arguments :
//      StoichNum - Stoichiometric numbers
// 
// ~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~

void CalcStoichNum( 
  double StoichNum[NVAR][NREACT]         /* Stoichiometric numbers */
)
{
  StoichNum[0][4] = 1;
  StoichNum[0][5] = -1;
  StoichNum[0][6] = -1;
  StoichNum[1][0] = 2;
  StoichNum[1][1] = -1;
  StoichNum[1][2] = 1;
  StoichNum[1][3] = -1;
  StoichNum[1][5] = 1;
  StoichNum[1][8] = -1;
  StoichNum[1][9] = 1;
  StoichNum[2][1] = 1;
  StoichNum[2][2] = -1;
  StoichNum[2][3] = -1;
  StoichNum[2][4] = -1;
  StoichNum[2][6] = -1;
  StoichNum[2][7] = -1;
  StoichNum[3][7] = -1;
  StoichNum[3][8] = 1;
  StoichNum[3][9] = 1;
  StoichNum[4][7] = 1;
  StoichNum[4][8] = -1;
  StoichNum[4][9] = -1;
}

// End of CalcStoichNum function
